import{_ as w,C as o,o as d,c as u,j as t,a,E as n,a8 as m}from"./chunks/framework.27XeWUA0.js";const r="/schedule-dashboard/thumbs/yt/q4ITwvlFplQ-640.webp",g="/schedule-dashboard/thumbs/yt/q4ITwvlFplQ-1280.webp",s="/schedule-dashboard/thumbs/yt/5SRjPT2Eo7A-640.webp",v="/schedule-dashboard/thumbs/yt/5SRjPT2Eo7A-1280.webp",i="/schedule-dashboard/thumbs/yt/JxNCuXkSWyQ-640.webp",b="/schedule-dashboard/thumbs/yt/JxNCuXkSWyQ-1280.webp",l="/schedule-dashboard/thumbs/yt/-X3yXTwGs9A-640.webp",y="/schedule-dashboard/thumbs/yt/-X3yXTwGs9A-1280.webp",h="/schedule-dashboard/thumbs/yt/vUJDyDnqT4c-640.webp",f="/schedule-dashboard/thumbs/yt/vUJDyDnqT4c-1280.webp",E=JSON.parse('{"title":"AI Digest · Tue 03 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-03","routine":"digest"},"relativePath":"digest/2026-11-03.md","filePath":"digest/[date].md"}'),k={name:"digest/2026-11-03.md"},_=r+" 640w, "+g+" 1280w",T=s+" 640w, "+v+" 1280w",A=i+" 640w, "+b+" 1280w",I=l+" 640w, "+y+" 1280w",S=h+" 640w, "+f+" 1280w",x={id:"ai-digest-·-tue-03-nov-2026",tabindex:"-1"};function q(X,e,R,C,N,D){const c=o("Badge"),p=o("DayFilter");return d(),u("div",null,[t("h1",x,[e[0]||(e[0]=a("AI Digest · Tue 03 Nov 2026 ",-1)),n(c,{type:"tip",text:"5"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-tue-03-nov-2026","aria-label":'Permalink to "AI Digest · Tue 03 Nov 2026 <Badge type="tip" text="5" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer daily digest — 3 Nov 2026 · run date Tue 03 Nov 2026 · 5 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(` 5 new talks in the last 24 hours, all with full transcripts. The freshest and most worth your time is Runway CEO Cristóbal Valenzuela (3 Nov, 5:30 AM IST) on video models becoming real-time, clickable world models and the "Continuum" research demos, which is genuinely new ground. Will Brown of Prime Intellect (3 Nov, 1:30 AM IST) makes the case for training your own models, and Apollo's airline crew-scheduling case is a concrete ROI talk. Speakeasy's agent control layer is partly familiar governance ground, and Sourcegraph's code-review-bottleneck talk is mostly a repeat apart from its customer examples.`)]),t("p",null,[t("strong",null,"Better Stack:"),a(" nothing new in the last 24 hours.")])],-1)),n(p),e[5]||(e[5]=m('<div class="grid cards2"><article class="it full" id="v-q4ITwvlFplQ" data-title="You Can&#39;t Tell What&#39;s Real Anymore. Here&#39;s What Comes Next - Cristóbal Valenzuela, Runway" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=q4ITwvlFplQ" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+_+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=q4ITwvlFplQ" target="_blank" rel="noopener">You Can&#39;t Tell What&#39;s Real Anymore. Here&#39;s What Comes Next - Cristóbal Valenzuela, Runway</a></h3><div class="meta">AI Engineer · Cristóbal Valenzuela, Runway (co-founder and CEO) · uploaded 3 Nov, 5:30 AM IST · 16:51</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — genuinely new ground for your history, and the demos from 6:50 on need to be seen rather than read.</div><div class="repeat">🔁 Repeat: &#39;multimodal models&#39; — seen 7 times before. New here: almost all of it; this is the first talk in the history on video models turning into real-time, clickable world models, plus Runway&#39;s unreleased &quot;Continuum&quot; research.</div><div class="sh">From an orange to photoreal</div><ul><li><strong>Where Runway started:</strong> Its first AI film, &quot;The Orange&quot; (2019), was generated at 128×128 pixels and upsampled; today&#39;s state-of-the-art clips have no real actors or locations, and Valenzuela expects them to look as dated as the orange within a couple of years (<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=46s" target="_blank" rel="noopener">0:46</a>–<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=137s" target="_blank" rel="noopener">2:17</a>)</li><li><strong>Next-frame prediction at scale:</strong> Video is the old cinema illusion of stitched frames, and Runway bets scaling laws apply to video as to language; they&#39;re ramping compute and say their own tests show people can no longer tell real from generated video (<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=137s" target="_blank" rel="noopener">2:17</a>–<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=274s" target="_blank" rel="noopener">4:34</a>)</li></ul><div class="sh">What video models learn</div><ul><li><strong>Physics for free:</strong> Predicting frames forces the model to learn gravity, occlusion, object permanence and how objects relate (a camel balancing on a ball), so Runway&#39;s benchmarks score physics and geometry, not just looks (<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=274s" target="_blank" rel="noopener">4:34</a>–<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=365s" target="_blank" rel="noopener">6:05</a>)</li><li><strong>Simulation without a physics engine:</strong> Run in a game-like environment, the same model behaves like a simulator with no coded rules, for example someone &quot;playing&quot; a game that doesn&#39;t exist (<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=365s" target="_blank" rel="noopener">6:05</a>–<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=410s" target="_blank" rel="noopener">6:50</a>)</li></ul><div class="sh">Real-time and interactive</div><ul><li><strong>Interactive world models and robots:</strong> Making generation real time lets you act at any frame and branch the world; half of Runway&#39;s New York office is now a robotics lab using these models as robot brains (<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=410s" target="_blank" rel="noopener">6:50</a>–<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=502s" target="_blank" rel="noopener">8:22</a>)</li><li><strong>World interface model:</strong> On a still photo of a car, clicks turn on the lights, spin it around and open the hood, with no 3D model, Unity, Unreal or Blender behind it; objects in a room photo can be moved the same way (<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=502s" target="_blank" rel="noopener">8:22</a>–<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=592s" target="_blank" rel="noopener">9:52</a>)</li></ul><div class="sh">Continuum (early research)</div><ul><li><strong>A video-model operating system:</strong> Select text on a web page (San Francisco fog) and turn it into an interactive real-time &quot;portal&quot;; past portals (batteries) are kept as a visual memory, and resizing the window changes a photosynthesis explainer (<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=592s" target="_blank" rel="noopener">9:52</a>–<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=820s" target="_blank" rel="noopener">13:40</a>)</li><li><strong>Visual thinking for coding agents:</strong> A coding agent asked for a 3D bike model can spin up Continuum to reason visually, and you can see and steer that &quot;imagination&quot; too (<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=820s" target="_blank" rel="noopener">13:40</a>–<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=905s" target="_blank" rel="noopener">15:05</a>)</li><li><strong>Live experiences and release plan:</strong> Searching for Mars generated an explorable outpost based on real and planned rovers; Runway plans to release most of what was shown in the next 8–12 months (<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=905s" target="_blank" rel="noopener">15:05</a>–<a href="https://www.youtube.com/watch?v=q4ITwvlFplQ&amp;t=1011s" target="_blank" rel="noopener">16:51</a>)</li></ul></div></article><article class="it full" id="v-5SRjPT2Eo7A" data-title="Your Company Should Train Its Own AI Models - Will Brown, Prime Intellect" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=5SRjPT2Eo7A" target="_blank" rel="noopener"><img src="'+s+'" srcset="'+T+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A" target="_blank" rel="noopener">Your Company Should Train Its Own AI Models - Will Brown, Prime Intellect</a></h3><div class="meta">AI Engineer · Will Brown, Prime Intellect (applied research lead) · uploaded 3 Nov, 1:30 AM IST · 20:16</div><div class="verdict v-skim"><b>Verdict:</b> skim from 8:06 — the telephone critique, widgets and $300K example are new; the evals and routing parts are well covered.</div><div class="repeat">🔁 Repeat: &#39;self-improving agents&#39; — seen 18 times before (including a whole August block on continual learning). New here: the &quot;game of telephone&quot; critique of how frontier labs learn your workflows, and on-the-fly decision widgets as clean training labels.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 52 times before, &#39;decision models&#39; 6 times, &#39;RL fine-tuning small models&#39; 5 times and &#39;open source / local models&#39; 49 times. New here: a $300K trained model and nightly training on idle inference capacity.</div><div class="sh">Why agents keep relearning</div><ul><li><strong>The unwritten company:</strong> Firms run on a &quot;real org chart&quot; and unwritten friction points; agents are good at combing unstructured text to spot patterns such as one team having already solved another team&#39;s problem (<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=225s" target="_blank" rel="noopener">3:45</a>–<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=332s" target="_blank" rel="noopener">5:32</a>)</li><li><strong>In-context learning is primitive:</strong> Agents rely on skill files and re-read the codebase each time; cached input is now the cost bottleneck, and preferences and heuristics are data that belong in the weights, once they&#39;ve &quot;earned&quot; it (<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=332s" target="_blank" rel="noopener">5:32</a>–<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=486s" target="_blank" rel="noopener">8:06</a>)</li><li><strong>The game of telephone:</strong> For a lab to learn, say, Salesforce workflows, an expert on an expert network passes knowledge to a network company, then an RL-environment builder, then a lab researcher; the person who actually knows never supervises the training (<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=486s" target="_blank" rel="noopener">8:06</a>–<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=604s" target="_blank" rel="noopener">10:04</a>)</li></ul><div class="sh">How to start</div><ul><li><strong>Treat the model like a codebase (repeat):</strong> Traces with your prompts and feedback become evals, essentially test cases, and agents can now write most of them (<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=649s" target="_blank" rel="noopener">10:49</a>–<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=763s" target="_blank" rel="noopener">12:43</a>)</li><li><strong>Routing and decision models (repeat):</strong> Run a big and a small model on the same task and judge whether the small one matched; human approvals become labels for a decision model, as with the recent Jev craze (<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=763s" target="_blank" rel="noopener">12:43</a>–<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=878s" target="_blank" rel="noopener">14:38</a>)</li><li><strong>Decision widgets:</strong> Instead of juggling 20 bot threads, agents generate small cards asking you for a decision; that&#39;s easier for you and gives a precise label that sidesteps reward hacking (<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=911s" target="_blank" rel="noopener">15:11</a>–<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=1047s" target="_blank" rel="noopener">17:27</a>)</li></ul><div class="sh">Where it leads</div><ul><li><strong>A $300K model:</strong> A company (name unclear in the captions) used Prime Intellect tooling to train a Pareto-optimal model for spreadsheets and slides for about $300K, which Brown compares to hiring one engineer (<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=1047s" target="_blank" rel="noopener">17:27</a>–<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=1107s" target="_blank" rel="noopener">18:27</a>)</li><li><strong>Nightly training runs:</strong> Their internal prototype reviews proposed experiments and flagged issues each night and trains on inference capacity that sits idle after hours (<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=1107s" target="_blank" rel="noopener">18:27</a>–<a href="https://www.youtube.com/watch?v=5SRjPT2Eo7A&amp;t=1198s" target="_blank" rel="noopener">19:58</a>)</li></ul></div></article><article class="it full" id="v-JxNCuXkSWyQ" data-title="A Valid Key Let an AI Agent Delete Production - Sagar Batchu, Speakeasy" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=JxNCuXkSWyQ" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+A+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ" target="_blank" rel="noopener">A Valid Key Let an AI Agent Delete Production - Sagar Batchu, Speakeasy</a></h3><div class="meta">AI Engineer · Sagar Batchu, Speakeasy (CEO and co-founder) · uploaded 2 Nov, 3:30 PM IST · 20:40</div><div class="verdict v-skim"><b>Verdict:</b> skim from 10:50 — the permission-intersection model and intent records are the new part; the rest is familiar governance ground.</div><div class="repeat">🔁 Repeat: &#39;agent security&#39; — seen 30 times before, &#39;AI in regulated industries&#39; 21 times, &#39;agent governance&#39; 11 times, &#39;AI gateway&#39; 8 times and &#39;agent identity&#39; 8 times. New here: a precise permission rule (an agent never exceeds its credential, its own policy or its owner&#39;s live rights) and intent-aware audit records.</div><div class="sh">The incident</div><ul><li><strong>Valid credentials, not valid intent:</strong> In the April incident, an agent fixing a staging credential found a full-access infrastructure token in an unrelated file and deleted the volume, which was production; the database and its backup were gone in about 10 seconds, with no exploit or prompt injection involved (<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=57s" target="_blank" rel="noopener">0:57</a>–<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=223s" target="_blank" rel="noopener">3:43</a>)</li><li><strong>Industry numbers:</strong> 82% of organisations run AI agents but only 32% have an AI governance policy, and a shadow-AI breach costs about $5M on average (<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=195s" target="_blank" rel="noopener">3:15</a>–<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=287s" target="_blank" rel="noopener">4:47</a>)</li></ul><div class="sh">The control layer</div><ul><li><strong>Make the governed path easier:</strong> Blocks get routed around, so policies are written once centrally and shipped via MDM from day one; in the demo a hook catches an AWS key in a prompt, blocks and logs it in under 100 ms (<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=326s" target="_blank" rel="noopener">5:26</a>–<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=506s" target="_blank" rel="noopener">8:26</a>)</li><li><strong>Connect, inspect, decide, record (repeat):</strong> One door for all tool calls (an MCP gateway), every call tied to a named agent or human from the company identity provider, then allow, deny, quarantine, escalate or warn, recorded before the action runs (<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=506s" target="_blank" rel="noopener">8:26</a>–<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=560s" target="_blank" rel="noopener">9:20</a>)</li><li><strong>Three identities per action:</strong> The agent is its own principal, the operator driving it is recorded but never widens access, and the authorizer (their CISO, Thomas) approved the credential for its lifetime (<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=560s" target="_blank" rel="noopener">9:20</a>–<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=650s" target="_blank" rel="noopener">10:50</a>)</li><li><strong>Permission intersection:</strong> An action needs the credential ceiling, the agent&#39;s own policy and the owner&#39;s live policy; the last two are re-read on every call, so a staging-scoped agent can&#39;t delete production and offboarding someone in the IdP denies all their agents (<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=650s" target="_blank" rel="noopener">10:50</a>–<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=771s" target="_blank" rel="noopener">12:51</a>)</li><li><strong>Intent-aware records:</strong> Each non-read action is checked against the agent&#39;s stated intent (staging) versus the real target (production), and the record is cryptographically bound to the agent&#39;s identity (<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=771s" target="_blank" rel="noopener">12:51</a>–<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=878s" target="_blank" rel="noopener">14:38</a>)</li></ul><div class="sh">Q&amp;A</div><ul><li><strong>PII handling:</strong> Blocking all PII would halt the business, so policies should target where PII goes (a public Slack channel, email); customers bring their own encryption keys or run the data plane in their VPC (<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=1105s" target="_blank" rel="noopener">18:25</a>–<a href="https://www.youtube.com/watch?v=JxNCuXkSWyQ&amp;t=1240s" target="_blank" rel="noopener">20:40</a>)</li></ul></div></article><article class="it full" id="v--X3yXTwGs9A" data-title="AI Writes Code Faster Than Your Team Can Review It - Andrew Norrish, Sourcegraph" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=-X3yXTwGs9A" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+I+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=-X3yXTwGs9A" target="_blank" rel="noopener">AI Writes Code Faster Than Your Team Can Review It - Andrew Norrish, Sourcegraph</a></h3><div class="meta">AI Engineer · Andrew Norrish, Sourcegraph (director of field engineering) · uploaded 2 Nov, 2:30 PM IST · 18:57</div><div class="verdict v-skim"><b>Verdict:</b> skim from 15:17 — only the customer examples are new; the rest retells the code-review bottleneck.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 31 times before (Laurie Voss, Aviator, Qodo, Greptile and others), and &#39;coding agents in production&#39; 59 times. New here: very little beyond three customer examples of agentic incident response.</div><div class="repeat">🔁 Repeat: &#39;agentic search&#39; — seen 6 times before. New here: a root-cause agent that finds the culprit commit from git history.</div><div class="sh">The bottleneck story (mostly repeat)</div><ul><li><strong>Review is the new bottleneck:</strong> At Sourcegraph&#39;s latest customer advisory board, &quot;how many heads can this save us&quot; didn&#39;t come up for the first time; the constraint moved from typing code to reviewing it (repeat) (<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=93s" target="_blank" rel="noopener">1:33</a>–<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=185s" target="_blank" rel="noopener">3:05</a>)</li><li><strong>Incidents land on SREs:</strong> Bigger, more frequent AI PRs get merged without a human looking, incidents get longer and more recurring, and hiring SREs can&#39;t keep up (repeat) (<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=185s" target="_blank" rel="noopener">3:05</a>–<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=277s" target="_blank" rel="noopener">4:37</a>)</li><li><strong>Industry numbers:</strong> About two-thirds of code expected to be AI-written by 2027, roughly twice as many PRs merged at more than twice the size, nearly double the review time, and almost half of developers admit they don&#39;t always verify AI code (repeat) (<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=413s" target="_blank" rel="noopener">6:53</a>–<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=596s" target="_blank" rel="noopener">9:56</a>)</li></ul><div class="sh">Where AI does work</div><ul><li><strong>Bounded domains:</strong> Vulnerability fixes, migrations and CVE remediation work best, and SRE and platform teams already run semi-autonomous runbooks, making them both the barometer and the biggest winners (<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=596s" target="_blank" rel="noopener">9:56</a>–<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=687s" target="_blank" rel="noopener">11:27</a>)</li><li><strong>The Sourcegraph pitch:</strong> A code graph plus search and Deep Search (agentic search) to find root causes &quot;in minutes instead of days&quot;, monitors that flag risky commits, and bulk changes across every repo (<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=733s" target="_blank" rel="noopener">12:13</a>–<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=917s" target="_blank" rel="noopener">15:17</a>)</li></ul><div class="sh">Customer examples</div><ul><li><strong>HackerOne triage:</strong> Sourcegraph&#39;s own security team pipes HackerOne webhooks into agentic search, which decides whether a report needs a fix, deeper review or can be ignored (<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=917s" target="_blank" rel="noopener">15:17</a>–<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=963s" target="_blank" rel="noopener">16:03</a>)</li><li><strong>Root-cause agent at a 5,000-developer firm:</strong> On downtime or an error spike it finds the deployed branch or tag (rarely main), searches git history for the culprit commit and author, then reverts and redeploys or hands the findings to SREs (<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=963s" target="_blank" rel="noopener">16:03</a>–<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=1008s" target="_blank" rel="noopener">16:48</a>)</li><li><strong>Monorepo review agent:</strong> A customer&#39;s in-house review agent runs evals over hundreds of historical branches, using Sourcegraph&#39;s read-only code finder instead of grep (<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=1008s" target="_blank" rel="noopener">16:48</a>–<a href="https://www.youtube.com/watch?v=-X3yXTwGs9A&amp;t=1098s" target="_blank" rel="noopener">18:18</a>)</li></ul></div></article><article class="it full" id="v-vUJDyDnqT4c" data-title="Your AI Pilots Won&#39;t Move the P&amp;L. Here&#39;s What Will - Adam Nahari, Apollo" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=vUJDyDnqT4c" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+S+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=vUJDyDnqT4c" target="_blank" rel="noopener">Your AI Pilots Won&#39;t Move the P&amp;L. Here&#39;s What Will - Adam Nahari, Apollo</a></h3><div class="meta">AI Engineer · Adam Nahari, Apollo Global Management · uploaded 2 Nov, 1:30 PM IST · 15:52</div><div class="verdict v-worth"><b>Verdict:</b> worth watching if you lead AI rollouts — short, concrete and better grounded than most ROI talks.</div><div class="repeat">🔁 Repeat: &#39;AI ROI measurement&#39; — seen 11 times before, and &#39;AI fluency / enablement&#39; 9 times. New here: a concrete airline crew-scheduling case and explicit kill metrics (90-day gate, A/B gate, 50% adoption gate).</div><div class="sh">The gap</div><ul><li><strong>The crew desk:</strong> When a cargo aircraft fails, a scheduler has 15 minutes to re-crew the flight by hand, juggling rest rules, qualifications and locations, often falling back to premium pay; crew is the second-biggest cost after fuel (<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=1s" target="_blank" rel="noopener">0:01</a>–<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=82s" target="_blank" rel="noopener">1:22</a>)</li><li><strong>Adoption vs profit:</strong> 55% of US adults used generative AI within 3 years (the PC was at 20% and the internet at 30% at the same point), almost 90% of businesses use AI, but only 6% see significant EBIT impact; time saved adds up to about 2% of US work hours (<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=46s" target="_blank" rel="noopener">0:46</a>–<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=162s" target="_blank" rel="noopener">2:42</a>)</li><li><strong>Five to one:</strong> In every transformation he has seen, there are five units of change management for every unit of engineering, and the engineering share keeps shrinking (<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=137s" target="_blank" rel="noopener">2:17</a>–<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=222s" target="_blank" rel="noopener">3:42</a>)</li><li><strong>Three layers:</strong> General copilots get competed away into price, domain copilots help retrieval, and core operational systems keep gains in margin; companies with EBIT impact are 3x more likely to redesign a whole workflow (<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=222s" target="_blank" rel="noopener">3:42</a>–<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=345s" target="_blank" rel="noopener">5:45</a>)</li></ul><div class="sh">The six moves</div><ul><li><strong>Start from the P&amp;L:</strong> The airline&#39;s drivers were routes, tails, maintenance and crew, and they picked crew only; a good problem moves a line the CFO recognises, has a baseline agreed upfront, data the company owns, a named champion and is a CEO top-five priority (<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=327s" target="_blank" rel="noopener">5:27</a>–<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=441s" target="_blank" rel="noopener">7:21</a>)</li><li><strong>10% vs 10x:</strong> Rather than a faster tool for the scheduler, they built an optimisation engine that lists every legal crew solution ranked by cost in under a minute, plus a redesigned workflow and decision-support app (<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=441s" target="_blank" rel="noopener">7:21</a>–<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=542s" target="_blank" rel="noopener">9:02</a>)</li><li><strong>Owners first:</strong> No public CEO commitment means no funding; the VP of crew scheduling co-sponsored, scheduler champions met engineers every other day, and they hired a CIO, a VP of data and AI and a senior director of data science (<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=542s" target="_blank" rel="noopener">9:02</a>–<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=702s" target="_blank" rel="noopener">11:42</a>)</li><li><strong>Tools and kill metrics:</strong> Three of four executives at one workshop had never used AI before that week; each stage got a 90-day time gate, an A/B metric gate and an adoption gate of over 50% of schedulers, and the CFO checked unit costs including tokens (<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=702s" target="_blank" rel="noopener">11:42</a>–<a href="https://www.youtube.com/watch?v=vUJDyDnqT4c&amp;t=846s" target="_blank" rel="noopener">14:06</a>)</li></ul></div></article></div>',1))])}const Q=w(k,[["render",q]]);export{E as __pageData,Q as default};
